<section class="aec-carousel-section" data-aec-carousel data-autoplay="{{ $carousel['autoplay'] ? '1' : '0' }}" data-interval="{{ $carousel['interval_ms'] }}" style="--aec-desktop-cards:{{ $carousel['desktop_cards'] }};--aec-mobile-cards:{{ $carousel['mobile_cards'] }};">
    <div class="aec-carousel-heading"><h2>{{ $carousel['title'] }}</h2></div>
    <div class="aec-carousel-shell">
        @if($carousel['show_arrows'])<button type="button" class="aec-carousel-arrow" data-aec-prev aria-label="Previous items">‹</button>@endif
        <div class="aec-carousel-track" data-aec-track tabindex="0" aria-label="{{ $carousel['title'] }}">
            @foreach($carousel['items'] as $item)
                <article class="aec-carousel-card">
                    @if($item['image_url'])<img src="{{ $item['image_url'] }}" alt="" loading="lazy">@endif
                    <div class="aec-carousel-card__body"><h3>{{ $item['title'] }}</h3>@if($item['description'])<p>{{ $item['description'] }}</p>@endif
                    @if($item['link_url'])<a href="{{ $item['link_url'] }}">Explore →</a>@endif</div>
                </article>
            @endforeach
        </div>
        @if($carousel['show_arrows'])<button type="button" class="aec-carousel-arrow" data-aec-next aria-label="Next items">›</button>@endif
    </div>
    @if($carousel['show_dots'])<div class="aec-carousel-dots" data-aec-dots aria-label="Carousel pages"></div>@endif
</section>
<style>
.aec-carousel-section{margin:34px 0;padding:clamp(22px,4vw,44px);border-radius:22px;background:#f5f8fc;color:#16324a}.aec-carousel-heading{max-width:1100px;margin:0 auto 20px}.aec-carousel-heading h2{font-size:clamp(1.5rem,3vw,2.2rem);font-weight:800}.aec-carousel-shell{display:flex;align-items:center;gap:10px;max-width:1160px;margin:auto}.aec-carousel-track{display:flex;flex:1;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;overscroll-behavior-inline:contain;scrollbar-width:thin;padding:5px 2px 16px}.aec-carousel-card{display:flex;flex:0 0 calc((100% - (var(--aec-desktop-cards) - 1)*16px)/var(--aec-desktop-cards));min-width:0;flex-direction:column;overflow:hidden;border:1px solid #dbe5ef;border-radius:16px;background:#fff;scroll-snap-align:start;box-shadow:0 8px 22px #18324a0b}.aec-carousel-card img{width:100%;height:160px;object-fit:cover}.aec-carousel-card__body{display:flex;flex:1;flex-direction:column;gap:8px;padding:18px}.aec-carousel-card h3{font-size:1.05rem;font-weight:800}.aec-carousel-card p{color:#61758a;font-size:.9rem;line-height:1.6}.aec-carousel-card a{margin-top:auto;color:#0876b7;font-weight:700}.aec-carousel-arrow{flex:0 0 38px;height:38px;border:1px solid #cbd8e5;border-radius:50%;background:#fff;color:#18344a;font-size:24px}.aec-carousel-dots{display:flex;justify-content:center;gap:7px;margin-top:12px}.aec-carousel-dots button{width:8px;height:8px;padding:0;border:0;border-radius:99px;background:#91a7ba}.aec-carousel-dots button[aria-current=true]{width:23px;background:#087dbb}@media(max-width:800px){.aec-carousel-card{flex-basis:calc((100% - 16px)/var(--aec-mobile-cards))}.aec-carousel-section{margin:24px 0;padding:20px 12px}.aec-carousel-arrow{flex-basis:32px;height:32px}}@media(prefers-reduced-motion:reduce){.aec-carousel-track{scroll-behavior:auto}}
</style>
<script>
document.querySelectorAll('[data-aec-carousel]:not([data-initialized])').forEach(section=>{section.dataset.initialized='1';const track=section.querySelector('[data-aec-track]'),prev=section.querySelector('[data-aec-prev]'),next=section.querySelector('[data-aec-next]'),dots=section.querySelector('[data-aec-dots]');if(!track)return;const cards=[...track.children],step=()=>Math.max(1,track.clientWidth);let pages=0;const renderDots=()=>{if(!dots)return;const count=Math.max(1,Math.ceil(track.scrollWidth/step()));if(count===pages&&dots.childElementCount===count)return;pages=count;dots.replaceChildren();for(let i=0;i<pages;i++){const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Go to carousel page '+(i+1));b.addEventListener('click',()=>track.scrollTo({left:i*step(),behavior:'smooth'}));dots.appendChild(b);}};const update=()=>{const page=Math.min(pages-1,Math.round(track.scrollLeft/step()));if(prev)prev.disabled=track.scrollLeft<=2;if(next)next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-2;if(dots)[...dots.children].forEach((b,i)=>b.setAttribute('aria-current',String(i===page)));};const refresh=()=>{renderDots();update();};prev?.addEventListener('click',()=>track.scrollBy({left:-step(),behavior:'smooth'}));next?.addEventListener('click',()=>track.scrollBy({left:step(),behavior:'smooth'}));track.addEventListener('scroll',()=>requestAnimationFrame(update),{passive:true});track.addEventListener('keydown',e=>{if(e.key==='ArrowRight')track.scrollBy({left:step(),behavior:'smooth'});if(e.key==='ArrowLeft')track.scrollBy({left:-step(),behavior:'smooth'});});let timer=null;const start=()=>{if(timer!==null||section.dataset.autoplay!=='1'||window.matchMedia('(prefers-reduced-motion: reduce)').matches||cards.length<2)return;timer=window.setInterval(()=>{if(track.scrollLeft+track.clientWidth>=track.scrollWidth-3)track.scrollTo({left:0,behavior:'smooth'});else track.scrollBy({left:step(),behavior:'smooth'});},Math.max(2500,Math.min(15000,Number(section.dataset.interval)||5000)));};const stop=()=>{if(timer!==null){window.clearInterval(timer);timer=null;}};section.addEventListener('mouseenter',stop);section.addEventListener('mouseleave',start);section.addEventListener('focusin',stop);section.addEventListener('focusout',start);window.addEventListener('resize',refresh,{passive:true});track.querySelectorAll('img').forEach(img=>{if(!img.complete)img.addEventListener('load',refresh,{once:true});});if('ResizeObserver'in window){const observer=new ResizeObserver(refresh);observer.observe(track);section.querySelectorAll('img').forEach(img=>observer.observe(img));}refresh();start();});
</script>